namespace LabMonitoring.Domain.Facilities;

/// <summary>A workstation running the LabAgent (SRS FR-5.2, FR-5.3).</summary>
public class Computer
{
    public int Id { get; set; }

    public int RoomId { get; set; }
    public Room Room { get; set; } = null!;

    public string Name { get; set; } = null!;

    /// <summary>Hardware GUID generated by the Agent at install time.</summary>
    public Guid MachineId { get; set; }

    /// <summary>Hash of the per-machine AgentSecret used to sign commands. Plaintext is returned only once, at register.</summary>
    public string AgentSecretHash { get; set; } = null!;

    /// <summary>SHA-256 hash of the opaque AgentToken presented on every Agent request. Rotate to revoke a machine.</summary>
    public string AgentTokenHash { get; set; } = null!;

    /// <summary>Self-registered machines start unapproved (SRS FR-5.3); an admin approves them in M1.</summary>
    public bool IsApproved { get; set; }

    public string? MacAddress { get; set; }

    /// <summary>Coordinates on the room layout.</summary>
    public int? PositionX { get; set; }
    public int? PositionY { get; set; }

    public string? AgentVersion { get; set; }
    public bool IsActive { get; set; } = true;
    public DateTime CreatedAt { get; set; }

    public ComputerSpec? Spec { get; set; }
    public ComputerStatus? Status { get; set; }
    public ICollection<ComputerMetric> Metrics { get; set; } = [];
}
